package cli

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/teandresmith/sqlgen/cmd/sqlgen/config"
)

// driverForDialect returns the default driver for a given SQL dialect.
func driverForDialect(dialect string) string {
	if dialect == "postgres" {
		return "pgx"
	}
	return "stdlib"
}

// initConfigContent returns the starter config YAML for the given dialect.
func initConfigContent(dialect string) string {
	return fmt.Sprintf(`%s
# Generated by sqlgen init
input:
  dialect: %s
  paths:
    - "./migrations"

output:
  driver: %s
  dir: ./internal/models
  package: models
  layout: file_per_table
`, config.SchemaModeline, dialect, driverForDialect(dialect))
}

// runInit creates a starter sqlgen.yml config file. When interactive is true,
// it prompts for dialect selection via the provided reader and writer.
func runInit(out io.Writer, in io.Reader, interactive bool) error {
	for _, name := range []string{"sqlgen.yml", "sqlgen.yaml"} {
		if _, err := os.Stat(name); err == nil {
			return fmt.Errorf("%s already exists in the current directory", name)
		}
	}

	dialect := "postgres"

	if interactive {
		_, _ = fmt.Fprintln(out, "Select a dialect:")
		_, _ = fmt.Fprintln(out, "  1) postgres (default)")
		_, _ = fmt.Fprintln(out, "  2) mysql")
		_, _ = fmt.Fprintln(out, "  3) sqlite")
		_, _ = fmt.Fprint(out, "Enter choice [1]: ")

		scanner := bufio.NewScanner(in)
		if scanner.Scan() {
			choice := strings.TrimSpace(scanner.Text())
			switch choice {
			case "", "1", "postgres":
				dialect = "postgres"
			case "2", "mysql":
				dialect = "mysql"
			case "3", "sqlite":
				dialect = "sqlite"
			default:
				return fmt.Errorf("invalid dialect choice: %q", choice)
			}
		}
	}

	if err := os.WriteFile("sqlgen.yml", []byte(initConfigContent(dialect)), 0o600); err != nil {
		return fmt.Errorf("writing sqlgen.yml: %w", err)
	}

	_, _ = fmt.Fprintf(out, "Created sqlgen.yml (dialect: %s, driver: %s)\n", dialect, driverForDialect(dialect))
	return nil
}
